/// <summary>
/// designed by AVA WEN from AX2009 KCS_QuotationStatusModify
/// </summary>
public class AVAQuotationStatusModify extends RunBase
{
    SalesQuotationTable     salesQuotationTable;

    KCS_StatusId                kcs_StatusId;
    smmQuotationReasonId        kcs_ReasonId;
    KCS_StatusId                kcs_AltStatusId;
    TransDate                   kcs_DecisionDate;
    KCS_CompetitorId            kcs_CompetitorId;
    DirPartyName                kcs_Competitor;
    NoYesid                     kcs_SetDecisionDate;
    QuotationIdBase             kcs_QuotationId;
    KCS_KBVBuildingProjectID    kcs_KBVBuildingProjectID;
    KCS_DirProductGroupID       kcs_KBVProductGroupID;
    SalesQuotationStatus        kcs_QuotStatus;

    #define.CurrentVersion(1)

    #localmacro.CurrentList
        kcs_StatusId,
        kcs_ReasonId,
        kcs_AltStatusId,
        kcs_DecisionDate,
        kcs_CompetitorId,
        kcs_Competitor,
        kcs_SetDecisionDate,
        kcs_QuotationId,
        kcs_KBVBuildingProjectID,
        kcs_KBVProductGroupID,
        kcs_QuotStatus
    #endmacro


}

