public static void main(Args _args)
{
    SalesQuotationTable     sql;

    if (_args.dataset() == tableNum(SalesQuotationTable) && _args.record())
    {
        sql = _args.record();
    }

    AVAQuotationStatusModify    quotStatusModify = new AVAQuotationStatusModify(sql);
    quotStatusModify.init();
    quotStatusModify.runOperationNow();
}

KCS_StatusId parmAltStatusId(KCS_StatusId _kcs_AltStatusId = kcs_AltStatusId)
{
    kcs_AltStatusId = _kcs_AltStatusId;

    return kcs_AltStatusId;
}

DirPartyName parmComp(DirPartyName _kcs_Competitor = kcs_Competitor)
{
    kcs_Competitor = _kcs_Competitor;

    return kcs_Competitor;
}

