{
    kcs_CompetitorId = _kcs_CompetitorId;

    return kcs_CompetitorId;
}

TransDate parmDecisionDate(TransDate _kcs_DecisionDate  = kcs_DecisionDate)
{
    kcs_DecisionDate = _kcs_DecisionDate;

    return kcs_DecisionDate;
}

KCS_KBVBuildingProjectID parmKBVBuildingProjectID(KCS_KBVBuildingProjectID _kcs_KBVBuildingProjectID = kcs_KBVBuildingProjectID)
{
    kcs_KBVBuildingProjectID = _kcs_KBVBuildingProjectID;

    return kcs_KBVBuildingProjectID;
}

KCS_DirProductGroupID parmKBVProductGroupID(KCS_DirProductGroupID _kcs_KBVProductGroupID = kcs_KBVProductGroupID)
{
