protected void new(SalesQuotationTable _salesQuotationTable)
{
    salesQuotationTable = _salesQuotationTable;

    super();
}

public static AVAQuotationStatusModify construct(Args _args)
{
    SalesQuotationTable     sqt;
    AVAQuotationStatusModify    AVAQuotationStatusModify;

    if (_args && _args.dataset() == tableNum(SalesQuotationTable))
    {
        sqt = _args.record();
    }
    AVAQuotationStatusModify = new AVAQuotationStatusModify(sqt);
    return AVAQuotationStatusModify;
}

public boolean init()
{
    boolean                 ret;
    KCS_QuotationStatus     kQS;

    ret = super();

    this.parmStatusId(salesQuotationTable.KCS_StatusId);
    if (!salesQuotationTable.KCS_DecisionDate)
    {
        this.parmDecisionDate(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()));
    }
    else
    {
        this.parmDecisionDate(salesQuotationTable.KCS_DecisionDate);
    }
    this.parmQuotationId(salesQuotationTable.QuotationId);
    this.parmKBVBuildingProjectID(salesQuotationTable.KCS_KBVBuildingProjectID);
    this.parmKBVProductGroupID(salesQuotationTable.KCS_KBVProductGroupID);

    select firstonly kQS where kQS.KCS_StatusId == salesQuotationTable.KCS_StatusId;
    this.parmReasonId(kQS.KCS_ReasonId);
    this.parmAltStatusId(kQS.KCS_AltStatusId);
    this.parmSetDecisionDate(kQS.KCS_SetDecisionDate);
    this.parmQuotationStatus(kQS.KCS_SalesQuotationStatus);
    this.parmCompId(kQS.KCS_CompetitorId);
    this.parmComp(kQS.KCS_Competitor);

    return ret;
}

protected boolean canRunInNewSession()
{
    boolean ret;

    ret = true;

    return ret;
}

public container pack()
{
    return [#CurrentVersion,#CurrentList];
}

public boolean unpack(container packedClass)
{
    Version version = RunBase::getVersion(packedClass);

    switch (version)
    {
        case #CurrentVersion:
            [version,#CurrentList] = packedClass;
            break;
        default:
            return false;
    }

    return true;
}

public ClassDescription caption()
{
    ClassDescription ret;

    ret = SysLabel::labelId2String("@NDX:NXAQuotStatusMod");

    return ret;
}

/// <summary>
/// designed by AVANADE
/// </summary>
void updateSalesQuotation()
{
    SalesQuotationTable     tblSalesQuotationTable;
    SalesQuotationTable     updSalesQuotationTable;
    KCS_QuotationStatus     quotationStatus;
    KCS_QuotationStatus     quotationStatusPre;
    DataAreaId              secondaryDataArea = AVASalesParameters::find().SecondaryDataAreaIdBPRequests;

    select firstonly kcs_SetDecisionDate from quotationStatusPre where quotationStatusPre.KCS_StatusId == this.parmStatusId();            

    ttsbegin;
    select forupdate tblSalesQuotationTable
    where tblSalesQuotationTable.QuotationId == this.parmQuotationId();
    tblSalesQuotationTable.KCS_StatusId = this.parmStatusId();
    if(quotationStatusPre.KCS_SetDecisionDate)
    {
        tblSalesQuotationTable.KCS_DecisionDate = this.parmDecisionDate();
    }
    tblSalesQuotationTable.KCS_CompetitorId = this.parmCompId();
    tblSalesQuotationTable.KCS_Competitor = this.parmComp();
    tblSalesQuotationTable.QuotationStatus = this.parmQuotationStatus();

    this.NDX_SalesQuotationTablesUpdated(tblSalesQuotationTable.QuotationId, tblSalesQuotationTable);      
    tblSalesQuotationTable.update();
    ttscommit;


    if(tblSalesQuotationTable.KCS_KBVBuildingProjectID)                        
    {
        if(this.parmAltStatusId())
        {
            //Daten des Folgekennzeichens
            select firstonly quotationStatus where quotationStatus.KCS_StatusId == this.parmAltStatusId();
            //Abrufen der anderen Angebote des Bauvorhabens
            while select tblSalesQuotationTable
            where (tblSalesQuotationTable.KCS_KBVBuildingProjectID == this.parmKBVBuildingProjectID() &&
                    tblSalesQuotationTable.KCS_KBVProductGroupID == this.parmKBVProductGroupID() &&
                    (tblSalesQuotationTable.QuotationStatus == SalesQuotationStatus::Sent || tblSalesQuotationTable.QuotationStatus == SalesQuotationStatus::Created) &&
                    tblSalesQuotationTable.QuotationId != this.parmQuotationId())
            {

                select forupdate updSalesQuotationTable where updSalesQuotationTable.RecId == tblSalesQuotationTable.RecId;

                ttsbegin;
                updSalesQuotationTable.KCS_DecisionDate = this.parmDecisionDate();
                updSalesQuotationTable.KCS_CompetitorId = quotationStatus.KCS_CompetitorId;
                updSalesQuotationTable.KCS_Competitor   = quotationStatus.KCS_Competitor;
                updSalesQuotationTable.ReasonId         = quotationStatus.KCS_ReasonId;
                updSalesQuotationTable.KCS_StatusId     = quotationStatus.KCS_StatusId;
                updSalesQuotationTable.QuotationStatus  = quotationStatus.KCS_SalesQuotationStatus;
                this.NDX_SalesQuotationTablesUpdated(tblSalesQuotationTable.QuotationId, updSalesQuotationTable);                   
                updSalesQuotationTable.update();
                ttscommit;
            }

            if (secondaryDataArea)
            {
                changecompany(secondaryDataArea)
                {
                    updSalesQuotationTable.clear();
                    while select forupdate updSalesQuotationTable 
                        where updSalesQuotationTable.KCS_KBVBuildingProjectID == this.parmKBVBuildingProjectID() &&
                        updSalesQuotationTable.KCS_KBVProductGroupID == this.parmKBVProductGroupID() &&
                        (updSalesQuotationTable.QuotationStatus == SalesQuotationStatus::Sent || updSalesQuotationTable.QuotationStatus == SalesQuotationStatus::Created)
                    {
                        ttsbegin;
                        updSalesQuotationTable.KCS_DecisionDate = this.parmDecisionDate();
                        updSalesQuotationTable.KCS_CompetitorId = quotationStatus.KCS_CompetitorId;
                        updSalesQuotationTable.KCS_Competitor   = quotationStatus.KCS_Competitor;
                        updSalesQuotationTable.ReasonId         = quotationStatus.KCS_ReasonId;
                        updSalesQuotationTable.KCS_StatusId     = quotationStatus.KCS_StatusId;
                        updSalesQuotationTable.QuotationStatus  = quotationStatus.KCS_SalesQuotationStatus;
                        updSalesQuotationTable.update();
                        ttscommit;
                    }
                }
            }

        }
    }
}

/// <summary>
/// from AX2009
/// </summary>
/// <param name = "salesQuotationIdBase">SalesQuotationId</param>
/// <param name = "salesQuotationTableUpdated">SalesQuotationTable</param>
void NDX_SalesQuotationTablesUpdated(SalesQuotationId salesQuotationIdBase, SalesQuotationTable salesQuotationTableUpdated)
{
}

/// <summary>
/// designed by AVANADE from AX2009
/// </summary>
/// <param name = "_salesQuotationTable">SalesQuotationTable</param>
/// <returns>boolean</returns>
boolean modifiedStatusId(SalesQuotationTable _salesQuotationTable)
{
    KCS_QuotationStatus     tblKCS_QuotationStatus;
    boolean ret;

    select firstonly tblKCS_QuotationStatus
    where tblKCS_QuotationStatus.KCS_StatusId == this.parmStatusId();

    // Folgekennzeichen (AltStatusId)
    this.parmAltStatusId(tblKCS_QuotationStatus.KCS_AltStatusId);

    // Angebotsstatus (QuotationStatus)
    this.parmQuotationStatus(tblKCS_QuotationStatus.KCS_SalesQuotationStatus);

    // Mitbewerberkennung (CompetitorId)
    if(tblKCS_QuotationStatus.KCS_CompetitorId)
    {
        this.parmComp(tblKCS_QuotationStatus.KCS_Competitor);
        this.parmCompId(tblKCS_QuotationStatus.KCS_CompetitorId);
    }
    else
    {
        this.parmComp();
        this.parmCompId();
    }

    // Entscheidungsdatum (DecisionDate)
    this.parmSetDecisionDate(tblKCS_QuotationStatus.KCS_SetDecisionDate);
    if(tblKCS_QuotationStatus.KCS_SetDecisionDate == NoYes::Yes)
    {
        if(this.parmDecisionDate() == datenull())
        {
            this.parmDecisionDate(DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()));
        }
    }


    // Grund (ReasonId)
    this.parmReasonId(tblKCS_QuotationStatus.KCS_ReasonId);

    ret = true;

    return ret;
}

protected void runOperationNow()
{
    FormRun     dialogForm;
    Args        args = new Args(formstr(AVAQuotationStatusModify));
    args.caller(this);

    dialogForm = classFactory.formRunClass(args);
    dialogForm.init();
    dialogForm.run();
    dialogForm.wait();

    if (dialogForm.closedOk())
    {
        this.updateSalesQuotation();
    }
}
